"""`W6-03`/`W6-04`: tài liệu đối mặt ra ngoài phải nói đúng, và phải bị canh.⭐⭐ **README cũ khai `W4 0/13`, `W5 0/11`, `W6 0/8` — "chưa bắt đầu" — trong khi cảba giai đoạn ấy đã xong hoặc gần xong, và nó khai "1.436 tests" khi đã có 2.853.**Nó sai suốt ba tuần và không có gì đỏ, vì không có gì đọc nó. Đó là chế độ hỏngđặc trưng của tài liệu: nó không hỏng, nó chỉ **thôi đúng**.DoD của `W6-03` là *"không có số nào không truy được về `reports/`"*. Một câu nhưthế chỉ có nghĩa nếu có thứ kiểm được nó, nên bài test này kiểm hai thứ máy kiểmđược:1. **Mọi liên kết nội bộ phân giải được.** Một tài liệu dẫn tới báo cáo không tồn   tại thì lời hứa "truy được về `reports/`" là lời hứa suông.2. **Mọi metric trích từ bundle khớp với chính manifest.** Đây là nhóm số dễ mục   nhất: bundle lên phiên bản mới thì bảng trong README thành số của một hệ thống   không còn chạy nữa — và vẫn trông hoàn toàn bình thường.⚠️ Cố ý **không** kiểm số lượng test và số file. Chúng đổi mỗi commit, nên mộtphép kiểm như vậy sẽ đỏ vì lý do vô hại tới mức người ta học cách sửa con số choxanh mà không đọc. Một phép kiểm bị làm cho xanh theo phản xạ tệ hơn không có."""from __future__ import annotationsimport jsonimport refrom pathlib import Pathfrom typing import Anyimport pytest_REPO_ROOT = Path(__file__).resolve().parents[2]DOCS = ("README.md", "README.vi.md", "ARCHITECTURE.md", "EVALUATION.md", "BUNDLE.md")# Metric nào của bundle được trích ra tài liệu, và số chữ số thập phân của nó.QUOTED_METRICS = {    "retrieval_metrics": ("ndcg@10", "recall@10", "recall@5", "mrr", "hit_rate@1", "map@20"),    "generation_metrics": ("faithfulness", "citation_coverage", "answer_relevancy"),}def _manifest() -> dict[str, Any]:    version = (_REPO_ROOT / "bundles" / "CURRENT").read_text(encoding="utf-8").strip()    path = _REPO_ROOT / "bundles" / f"rag-bundle-v{version}" / "manifest.json"    loaded: dict[str, Any] = json.loads(path.read_text(encoding="utf-8"))    return loaded@pytest.mark.parametrize("doc", DOCS)def test_every_internal_link_resolves(doc: str) -> None:    text = (_REPO_ROOT / doc).read_text(encoding="utf-8")    links = {m for m in re.findall(r"\]\(([^)#][^)]*)\)", text) if not m.startswith("http")}    broken = sorted(link for link in links if not (_REPO_ROOT / link).exists())    assert not broken, f"{doc} dẫn tới đường dẫn không tồn tại: {broken}"@pytest.mark.parametrize("doc", DOCS)def test_it_links_at_least_one_report(doc: str) -> None:    """Một tài liệu nêu số mà không dẫn về `reports/` thì DoD không kiểm được."""    text = (_REPO_ROOT / doc).read_text(encoding="utf-8")    assert "plans/reports/" in text, f"{doc} không dẫn về `plans/reports/` chỗ nào"# Nhãn của metric trong bảng README. Cần bảng này vì phép kiểm phải soi **đúng# dòng** của metric, không phải soi cả file — xem docstring bên dưới.METRIC_LABELS = {    "ndcg@10": "nDCG@10",    "recall@10": "Recall@10",    "recall@5": "Recall@5",    "mrr": "MRR",    "hit_rate@1": "hit_rate@1",    "map@20": "MAP@20",    "faithfulness": "Faithfulness",    "citation_coverage": "Citation coverage",    "answer_relevancy": "Answer relevancy",}VI_LABELS = {"Citation coverage": "Citation coverage", "Faithfulness": "Faithfulness"}def _table_row(text: str, label: str) -> str:    """Dòng bảng markdown mở đầu bằng đúng nhãn ấy."""    for line in text.splitlines():        stripped = line.strip()        if stripped.startswith("|") and stripped.lstrip("| ").startswith(label):            return stripped    return ""@pytest.mark.parametrize(    ("group", "metric"),    [(g, m) for g, metrics in QUOTED_METRICS.items() for m in metrics],)def test_quoted_bundle_metrics_match_the_manifest(group: str, metric: str) -> None:    """⭐ Nhóm số dễ mục nhất: bundle lên phiên bản, bảng trong README ở lại.    So với **manifest của bundle mà `CURRENT` đang trỏ tới**, không với một hằng    số chép tay ở đây — nếu không thì bài test này chỉ là bản sao thứ ba của cùng    một con số, và nó sẽ mục cùng nhịp với thứ nó canh (họ `AU-12`).    ⚠️⚠️ Soi **đúng dòng bảng**, không soi cả file. Bản đầu chỉ hỏi    `english in readme`, và một lượt tiêm lỗi cho thấy nó vô dụng: đổi `**0.7079**`    trong bảng thành `**0.7100**` vẫn XANH, vì cùng con số ấy còn nằm trong một    câu văn phía dưới. Một phép kiểm "chuỗi có xuất hiện đâu đó không" luôn được    cứu bởi bản sao gần nhất của chính nó.    """    value = _manifest()["eval"][group][metric]    english = f"{value:.4f}"    # README tiếng Việt viết dấu phẩy thập phân, và đó là chính tả chứ không phải    # một định dạng khác của cùng một con số.    vietnamese = english.replace(".", ",")    label = METRIC_LABELS[metric]    readme = (_REPO_ROOT / "README.md").read_text(encoding="utf-8")    readme_vi = (_REPO_ROOT / "README.vi.md").read_text(encoding="utf-8")    row = _table_row(readme, label)    assert row, f"README.md không có dòng bảng nào cho `{label}`"    assert english in row, (        f"dòng `{label}` của README.md không mang {english}; bundle "        f"{_manifest()['bundle_version']} đã đổi mà bảng chưa cập nhật — {row}"    )    row_vi = _table_row(readme_vi, VI_LABELS.get(label, label))    assert row_vi, f"README.vi.md không có dòng bảng nào cho `{label}`"    assert vietnamese in row_vi, (        f"dòng `{label}` của README.vi.md không mang {vietnamese} — {row_vi}"    )def test_every_bundle_version_printed_in_the_docs_is_the_current_one() -> None:    """`BUNDLE.md` in một mẫu manifest, và mẫu ấy phải là bundle đang chạy.    ⚠️ Bản đầu chỉ hỏi `version in bundle_md` và một lượt tiêm cho thấy nó vô dụng:    đổi `"bundle_version": "0.2.1"` trong khối mẫu thành `"0.2.0"` vẫn XANH, vì    chuỗi `0.2.1` còn nằm ở tên file, ở nhãn sơ đồ và ở bảng §8. Nên kiểm **mọi**    giá trị `bundle_version` in ra, chứ không kiểm sự tồn tại của một chuỗi.    """    version = _manifest()["bundle_version"]    bundle_md = (_REPO_ROOT / "BUNDLE.md").read_text(encoding="utf-8")    printed = re.findall(r'"bundle_version":\s*"([^"]+)"', bundle_md)    assert printed, "BUNDLE.md không in mẫu manifest nào"    assert set(printed) == {version}, (        f"BUNDLE.md in bundle_version={sorted(set(printed))} nhưng CURRENT là {version}"    )    assert version in bundle_mddef test_no_other_golden_set_is_named_in_the_docs() -> None:    """⚠️ "Có nhắc tới `golden_v1`" là một phép kiểm mà một lần đổi tên MỘT PHẦN đi qua.    Lượt tiêm đổi lần xuất hiện đầu thành `golden_v2` và bài test cũ vẫn xanh, vì    bốn lần còn lại vẫn đúng. Phép kiểm đúng là **không có tên nào khác**.    """    golden = _manifest()["eval"]["golden_set"]    evaluation = (_REPO_ROOT / "EVALUATION.md").read_text(encoding="utf-8")    named = set(re.findall(r"golden_v[0-9]+", evaluation))    assert golden in named, f"EVALUATION.md không nói về `{golden}`"    assert named == {golden}, f"EVALUATION.md còn nhắc golden set khác: {sorted(named - {golden})}"def test_the_judge_kappa_is_quoted_wherever_generation_metrics_are() -> None:    """⚠️ Một metric sinh mà không kèm mức đồng thuận của judge là một số không có đơn vị.    `W5-04` đo được: chỉ đổi model judge thôi đã làm metric dịch 7,5 điểm. Nên chỗ    nào in faithfulness thì chỗ ấy phải in được κ.    """    kappa = _manifest()["eval"]["judge"]["kappa_vs_human"]    rounded = f"{kappa:.4f}"    for doc in ("README.md", "EVALUATION.md"):        text = (_REPO_ROOT / doc).read_text(encoding="utf-8")        if "faithfulness" not in text.lower():            continue        assert rounded in text or rounded.replace(".", ",") in text, (            f"{doc} nêu faithfulness nhưng không nêu κ={rounded} của judge"        )